// GitHub Pages serves every prerendered route as a directory, so the 200
// URL ends in "/" ("/projects" 301s to "/projects/"). Canonical and og:url
// must name the 200 URL, matching scripts/prerender.js and the sitemap.
export const withTrailingSlash = (url) => {
  try {
    const u = new URL(url);
    if (!u.pathname.endsWith("/")) u.pathname += "/";
    return u.toString();
  } catch {
    return url;
  }
};

function setMeta(attr, key, content) {
  if (key === "og:url") content = withTrailingSlash(content);
  let el = document.head.querySelector(`meta[${attr}="${key}"]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, key);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}

function setCanonical(url) {
  let el = document.head.querySelector('link[rel="canonical"]');
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", withTrailingSlash(url));
}

// Meta for /projects/:slug, derived from the same portfolio.js data that
// scripts/prerender.js uses — so the client-side title matches the static one.
function projectMeta(pathname) {
  const m = /^\/projects\/([^/]+)\/?$/.exec(pathname);
  if (!m) return null;
  const project = findProjectBySlug(projects.data, m[1]);
  if (!project) return null;
  const title = cleanName(project.name);
  const tech = (project.languages || [])
    .map((l) => l.name)
    .slice(0, 5)
    .join(", ");
  return {
    title: `${title} | Project by ${NAME}`,
    description: `${String(project.description || "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 155)}${tech ? ` Built with ${tech}.` : ""}`.slice(0, 300),
    path: pathname.replace(/\/$/, ""),
  };
}

// Meta for /learn/:track, derived from the same learnData.js the prerenderer
// reads — so the client-side title matches the static one.
function trackMeta(pathname) {
  const m = /^\/learn\/([^/]+)\/?$/.exec(pathname);
  if (!m) return null;
  // /learn/:id takes a path id (ai, ml, agentic) or a track id — the URL
  // shouldn't make the reader care which level of the outline they landed on.
  const learnPath = pathById(m[1]);
  if (learnPath) {
    return {
      title: `${learnPath.seoTitle || `Learn ${learnPath.label}`} | ${NAME}`,
      description: String(learnPath.blurb || "")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 300),
      path: pathname.replace(/\/$/, ""),
    };
  }

  const track = tracks.find((t) => t.id === m[1]);
  if (!track) return null;
  return {
    title: `${track.title} — ${track.tagline} | Learn with ${NAME}`,
    description: String(track.blurb || "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 300),
    path: pathname.replace(/\/$/, ""),
  };
}

export default function RouteSeo() {
  const { pathname } = useLocation();

  useEffect(() => {
    // /blog/:slug pages own their SEO (per-post title, og:image, JSON-LD
    // set inside AIBlog) — don't overwrite it with the generic /blog meta
    if (/^\/blog\/.+/.test(pathname)) return;

    // /learn/:track — each track gets its own title, snippet and canonical
    const track = trackMeta(pathname);
    if (track) {
      document.title = track.title;
      setMeta("name", "description", track.description);
      setMeta("property", "og:title", track.title);
      setMeta("property", "og:description", track.description);
      setCanonical(`${SITE_URL}${track.path}`);
      setMeta("property", "og:url", `${SITE_URL}${track.path}`);
      return;
    }

    // /projects/:slug — each project gets its own title, snippet and canonical
    const project = projectMeta(pathname);
    if (project) {
      document.title = project.title;
      setMeta("name", "description", project.description);
      setMeta("property", "og:title", project.title);
      setMeta("property", "og:description", project.description);
      setCanonical(`${SITE_URL}${project.path}`);
      setMeta("property", "og:url", `${SITE_URL}${project.path}`);
      return;
    }

    // Match the longest route prefix so /projects/xyz still resolves
    const base =
      Object.keys(ROUTE_META)
        .filter((r) => r !== "/" && pathname.startsWith(r))
        .sort((a, b) => b.length - a.length)[0] || "/";
    const meta = ROUTE_META[base];

    document.title = meta.title;
    setMeta("name", "description", meta.description);
    setMeta("property", "og:title", meta.title);
    setMeta("property", "og:description", meta.description);
    // "/" and "/home" render the same page — canonicalize both to the root
    const canonicalPath = base === "/home" ? "/" : base;
    setCanonical(`${SITE_URL}${canonicalPath === "/" ? "/" : canonicalPath}`);
    setMeta(
      "property",
      "og:url",
      `${SITE_URL}${canonicalPath === "/" ? "/" : canonicalPath}`
    );
  }, [pathname]);

  return null;
}
