import React, { useEffect, useRef, useState } from "react";

/* ============================================
   🚀 JETPACK ESCAPE — offline mini-game
   HOLD (space / mouse / touch) for gentle
   thrust, release to drift down. Dodge
   asteroids & comets, grab 📶 for combos,
   🛡️ shield and 🧲 magnet power-ups.

   Pure Canvas 2D + rAF, ZERO dependencies —
   deliberately not three.js so it stays light
   and works while the user is offline (a lazy
   3D chunk could never load without network).
   The 3D *look* (depth starfield, shaded sphere
   asteroids, atmospheric planet, vignette) is
   all faked cheaply in 2D.
   ============================================ */

const W = 680; // logical width stays fixed → horizontal difficulty is unchanged
const BASE_H = 300; // desktop height; mobile gets a taller portrait field
const TAU = Math.PI * 2;
const BEST_KEY = "offline-jetpack-best";
const LEVEL_DIST = 2200; // distance per level

// Each stage gets its own sky gradient, planet palette and nebula tint
const LEVELS = [
  { name: "Open Space",  top: "#070c16", bottom: "#0d1930", planet: ["#4d7fb8", "#12294a"], neb: [42, 92, 150] },
  { name: "Debris Belt", top: "#0a0e1c", bottom: "#1a1436", planet: ["#7a55b0", "#241640"], neb: [110, 74, 165] },
  { name: "Comet Storm", top: "#120a1e", bottom: "#2a1040", planet: ["#b45585", "#3a1030"], neb: [175, 66, 116] },
  { name: "Ion Nebula",  top: "#061420", bottom: "#0a3040", planet: ["#33b0ac", "#0a3540"], neb: [46, 184, 180] },
  { name: "Deep Void",   top: "#0d0612", bottom: "#30102a", planet: ["#9a447a", "#30102a"], neb: [158, 58, 118] },
];

export default function OfflineGame() {
  const canvasRef = useRef(null);
  const [best, setBest] = useState(() => {
    try {
      return parseInt(localStorage.getItem(BEST_KEY), 10) || 0;
    } catch (e) {
      return 0;
    }
  });

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    // ---- responsive canvas ----
    // Width stays W (all horizontal tuning intact). On a portrait phone we
    // grow the logical HEIGHT so the game fills the screen instead of being a
    // short letterbox strip — more vertical room to fly, obstacles spread out
    // more. Physics is scaled by `vs` so the control feel stays consistent.
    let H = BASE_H;
    let vs = 1; // vertical scale = H / BASE_H
    const setupCanvas = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const portrait = window.innerHeight >= window.innerWidth;
      const dispW = Math.min(
        (canvas.parentElement && canvas.parentElement.clientWidth) || W,
        W
      );
      if (portrait && window.innerWidth < 760) {
        // aim for the game to occupy ~58% of the viewport height
        const targetDispH = Math.min(window.innerHeight * 0.58, 560);
        H = Math.max(380, Math.min(1100, Math.round((W * targetDispH) / dispW)));
      } else {
        H = BASE_H;
      }
      vs = H / BASE_H;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = "100%";
      canvas.style.height = "auto";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // draw in logical W×H units, crisp on retina
    };
    setupCanvas();

    // ---- state ----
    const S = {
      mode: "idle", // idle | play | dead
      y: H / 2,
      vy: 0,
      thrust: false,
      speed: 2.6,
      dist: 0,
      score: 0,
      level: 1,
      levelBanner: 0,
      combo: 0,
      comboTimer: 0,
      packets: 0,
      shield: false,
      magnet: 0, // frames remaining
      shake: 0,
      frame: 0,
      raf: 0,
      asteroids: [], // {x,y,r,rot,vr,vy,passed}
      comets: [], // {x,y,vx,vy,r}
      wifis: [], // {x,y,pulse}
      powerups: [], // {x,y,kind:'shield'|'magnet',pulse}
      particles: [],
      popups: [],
      spawnAst: 90,
      spawnWifi: 80,
      spawnPow: 700,
      deadCooldown: 0,
    };

    // Depth starfield: z in 0(far)..1(near). Near stars are bigger,
    // brighter, move faster and streak into lines at speed → real
    // sense of flying through 3D space.
    const stars = Array.from({ length: 150 }, () => ({
      x: Math.random() * W,
      y: Math.random() * H,
      z: Math.random(),
    }));

    // Drifting nebula clouds (soft radial blobs) for atmospheric depth
    const nebulae = Array.from({ length: 3 }, (_, i) => ({
      x: (i * 263) % W,
      y: 40 + ((i * 151) % (H - 80)),
      r: 90 + (i % 3) * 45,
      spd: 0.06 + (i % 3) * 0.04,
    }));

    // A single big background planet with atmosphere, slow parallax drift
    const planet = { x: W * 0.76, y: H * 0.32, r: 64 };

    const reset = () => {
      Object.assign(S, {
        mode: "play",
        y: H / 2,
        vy: 0,
        speed: 2.6,
        dist: 0,
        score: 0,
        level: 1,
        levelBanner: 100,
        combo: 0,
        comboTimer: 0,
        packets: 0,
        shield: false,
        magnet: 0,
        asteroids: [],
        comets: [],
        wifis: [],
        powerups: [],
        particles: [],
        popups: [],
        spawnAst: 90,
        spawnWifi: 80,
        spawnPow: 500,
      });
    };

    // ---- input: hold to thrust ----
    const press = (e) => {
      if (e.type === "keydown" && e.code !== "Space" && e.code !== "ArrowUp")
        return;
      if (e.cancelable) e.preventDefault();
      if (S.mode === "idle") reset();
      else if (S.mode === "dead") {
        if (S.deadCooldown <= 0) reset();
      } else S.thrust = true;
    };
    const release = () => {
      S.thrust = false;
    };
    window.addEventListener("keydown", press);
    window.addEventListener("keyup", release);
    canvas.addEventListener("pointerdown", press);
    window.addEventListener("pointerup", release);
    // recompute size on rotate / resize; keep the astronaut in-bounds
    const onResize = () => {
      setupCanvas();
      S.y = Math.max(20, Math.min(H - 20, S.y));
    };
    window.addEventListener("resize", onResize);

    // ---- helpers ----
    const burst = (x, y, color, n, power) => {
      for (let i = 0; i < n; i++) {
        const a = Math.random() * Math.PI * 2;
        const v = (0.5 + Math.random()) * power;
        S.particles.push({
          x,
          y,
          vx: Math.cos(a) * v,
          vy: Math.sin(a) * v,
          life: 30 + Math.random() * 20,
          max: 50,
          color,
          r: 1.5 + Math.random() * 2.5,
        });
      }
    };

    const popup = (x, y, text, color) => {
      S.popups.push({ x, y, text, life: 50, color: color || "#00d4a0" });
    };

    // Shaded sphere-rock asteroid (lit top-left, dark terminator + craters)
    const drawAsteroid = (a) => {
      ctx.save();
      ctx.translate(a.x, a.y);
      ctx.rotate(a.rot);
      // irregular silhouette
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const ang = (i / 8) * Math.PI * 2;
        const rr = a.r * (0.82 + 0.18 * Math.sin(i * 2.7));
        i === 0
          ? ctx.moveTo(Math.cos(ang) * rr, Math.sin(ang) * rr)
          : ctx.lineTo(Math.cos(ang) * rr, Math.sin(ang) * rr);
      }
      ctx.closePath();
      // radial gradient = 3D lit rock
      const grd = ctx.createRadialGradient(
        -a.r * 0.4,
        -a.r * 0.4,
        a.r * 0.1,
        0,
        0,
        a.r * 1.15
      );
      grd.addColorStop(0, "#9aa5b6");
      grd.addColorStop(0.45, "#57616f");
      grd.addColorStop(1, "#20262f");
      ctx.fillStyle = grd;
      ctx.fill();
      // craters (shaded)
      const crater = (cx, cy, cr) => {
        const cg = ctx.createRadialGradient(cx - cr * 0.3, cy - cr * 0.3, 0, cx, cy, cr);
        cg.addColorStop(0, "rgba(20,24,30,.75)");
        cg.addColorStop(1, "rgba(60,68,80,.1)");
        ctx.fillStyle = cg;
        ctx.beginPath();
        ctx.arc(cx, cy, cr, 0, TAU);
        ctx.fill();
      };
      crater(-a.r * 0.28, -a.r * 0.15, a.r * 0.24);
      crater(a.r * 0.3, a.r * 0.28, a.r * 0.16);
      crater(a.r * 0.05, a.r * 0.4, a.r * 0.1);
      // rim light on the lit edge
      ctx.strokeStyle = "rgba(190,205,225,.35)";
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(0, 0, a.r * 0.92, Math.PI * 1.05, Math.PI * 1.75);
      ctx.stroke();
      ctx.restore();
    };

    const hit = (x, y) => {
      if (S.shield) {
        // shield absorbs the hit
        S.shield = false;
        S.shake = 8;
        burst(x, y, "#7df9ff", 26, 4);
        popup(90, S.y - 30, "shield saved you! 🛡️", "#7df9ff");
        return false;
      }
      S.mode = "dead";
      S.deadCooldown = 40;
      S.shake = 18;
      burst(90, S.y, "#ff6b6b", 40, 5);
      burst(90, S.y, "#ffd166", 25, 3.5);
      const sc = Math.floor(S.score);
      setBest((b) => {
        const nb = Math.max(b, sc);
        try {
          localStorage.setItem(BEST_KEY, String(nb));
        } catch (e) {
          /* private mode */
        }
        return nb;
      });
      return true;
    };

    // ---- main loop ----
    const loop = () => {
      S.raf = requestAnimationFrame(loop);
      S.frame++;
      if (S.deadCooldown > 0) S.deadCooldown--;

      const lv = LEVELS[Math.min(S.level - 1, LEVELS.length - 1)];
      const moving = S.mode === "play";

      // nebula sky gradient shifts per level
      ctx.clearRect(0, 0, W, H);
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, lv.top);
      g.addColorStop(1, lv.bottom);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);

      ctx.save();
      if (S.shake > 0) {
        S.shake *= 0.85;
        ctx.translate(
          (Math.random() - 0.5) * S.shake,
          (Math.random() - 0.5) * S.shake
        );
      }

      // ---- drifting nebula clouds (far depth) ----
      const [nr, ng, nb] = lv.neb;
      nebulae.forEach((n) => {
        if (moving) {
          n.x -= n.spd * (S.speed / 2.6);
          if (n.x < -n.r) {
            n.x = W + n.r;
            n.y = 40 + Math.random() * (H - 80);
          }
        }
        const ng2 = ctx.createRadialGradient(n.x, n.y, 0, n.x, n.y, n.r);
        ng2.addColorStop(0, `rgba(${nr},${ng},${nb},0.14)`);
        ng2.addColorStop(1, `rgba(${nr},${ng},${nb},0)`);
        ctx.fillStyle = ng2;
        ctx.beginPath();
        ctx.arc(n.x, n.y, n.r, 0, TAU);
        ctx.fill();
      });

      // ---- background planet with atmosphere ----
      if (moving) {
        planet.x -= 0.12 * (S.speed / 2.6);
        if (planet.x < -planet.r * 1.8) {
          planet.x = W + planet.r * 1.8;
          planet.y = H * (0.2 + Math.random() * 0.3);
        }
      }
      const [pHi, pLo] = lv.planet;
      // atmospheric glow
      const glow = ctx.createRadialGradient(
        planet.x,
        planet.y,
        planet.r * 0.85,
        planet.x,
        planet.y,
        planet.r * 1.7
      );
      glow.addColorStop(0, `${pHi}44`);
      glow.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(planet.x, planet.y, planet.r * 1.7, 0, TAU);
      ctx.fill();
      // planet body, lit top-left → terminator shadow
      const body = ctx.createRadialGradient(
        planet.x - planet.r * 0.4,
        planet.y - planet.r * 0.4,
        planet.r * 0.1,
        planet.x,
        planet.y,
        planet.r
      );
      body.addColorStop(0, pHi);
      body.addColorStop(0.65, pLo);
      body.addColorStop(1, "#05070c");
      ctx.globalAlpha = 0.85;
      ctx.fillStyle = body;
      ctx.beginPath();
      ctx.arc(planet.x, planet.y, planet.r, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;

      // ---- depth starfield (near stars streak at speed) ----
      stars.forEach((st) => {
        if (moving) {
          st.x -= (0.4 + st.z * 2.6) * (S.speed / 2.6);
          if (st.x < -6) {
            st.x = W + 6;
            st.y = Math.random() * H;
            st.z = Math.random();
          }
        }
        const size = 0.5 + st.z * 2.1;
        ctx.globalAlpha = 0.2 + st.z * 0.75;
        const streak = moving ? st.z * st.z * S.speed * 1.7 : 0;
        if (streak > 2) {
          ctx.strokeStyle = "#d7e8ff";
          ctx.lineWidth = size;
          ctx.lineCap = "round";
          ctx.beginPath();
          ctx.moveTo(st.x, st.y);
          ctx.lineTo(st.x + streak, st.y);
          ctx.stroke();
        } else {
          ctx.fillStyle = "#eaf2ff";
          ctx.beginPath();
          ctx.arc(st.x, st.y, size, 0, TAU);
          ctx.fill();
        }
      });
      ctx.globalAlpha = 1;

      if (S.mode === "play") {
        // ---- gentle physics: hold to hover, release to drift ----
        // scaled by vs so a taller mobile field feels the same as desktop
        S.vy += (S.thrust ? -0.26 : 0.16) * vs;
        S.vy = Math.max(-3.8 * vs, Math.min(4.2 * vs, S.vy));
        S.y += S.vy;

        // soft edges: bounce instead of dying
        if (S.y < 20) {
          S.y = 20;
          S.vy = Math.max(0, S.vy);
        }
        if (S.y > H - 20) {
          S.y = H - 20;
          S.vy = Math.min(0, S.vy);
        }

        S.dist += S.speed;
        S.score += 0.05 * S.speed;

        // ---- level progression: starts easy, hardens per level ----
        const newLevel = Math.floor(S.dist / LEVEL_DIST) + 1;
        if (newLevel > S.level) {
          S.level = newLevel;
          S.levelBanner = 100;
          S.shake = 5;
          burst(W / 2, H / 2, "#ffd166", 30, 4);
        }
        S.speed = 2.6 + (S.level - 1) * 0.4;

        if (S.magnet > 0) S.magnet--;
        if (S.comboTimer > 0) S.comboTimer--;
        else S.combo = 0;

        // jetpack exhaust
        if (S.thrust && S.frame % 2 === 0) {
          S.particles.push({
            x: 78,
            y: S.y + 14,
            vx: -2 - Math.random() * 2,
            vy: 1.5 + Math.random() * 1.5,
            life: 22,
            max: 22,
            color: Math.random() < 0.6 ? "#00d4a0" : "#7df9ff",
            r: 2 + Math.random() * 2.5,
          });
        }

        // spawn asteroids (sparse at level 1, denser later)
        if (--S.spawnAst <= 0) {
          const r = 13 + Math.random() * 18;
          S.asteroids.push({
            x: W + r,
            y: r + Math.random() * (H - 2 * r),
            r,
            rot: Math.random() * Math.PI * 2,
            vr: (Math.random() - 0.5) * 0.08,
            vy: (Math.random() - 0.5) * (0.4 + S.level * 0.15),
            passed: false,
          });
          const base = Math.max(34, 95 - S.level * 12);
          S.spawnAst = base * (0.75 + Math.random() * 0.5);
        }

        // comets from level 3: fast, diagonal, with trails
        if (S.level >= 3 && Math.random() < 0.004 + S.level * 0.0012) {
          S.comets.push({
            x: W + 20,
            y: 20 + Math.random() * (H - 40),
            vx: -(S.speed * 1.6 + 2.5),
            vy: (Math.random() - 0.5) * 2,
            r: 8,
          });
        }

        // wifi packets
        if (--S.spawnWifi <= 0) {
          S.wifis.push({
            x: W + 20,
            y: 30 + Math.random() * (H - 60),
            pulse: Math.random() * Math.PI * 2,
          });
          S.spawnWifi = 65 + Math.random() * 60;
        }

        // power-ups (shield / magnet), rare
        if (--S.spawnPow <= 0) {
          S.powerups.push({
            x: W + 20,
            y: 40 + Math.random() * (H - 80),
            kind: Math.random() < 0.55 ? "shield" : "magnet",
            pulse: 0,
          });
          S.spawnPow = 600 + Math.random() * 500;
        }
      }

      // ---- asteroids ----
      S.asteroids = S.asteroids.filter((a) => {
        if (S.mode === "play") {
          a.x -= S.speed;
          a.y += a.vy;
          a.rot += a.vr;
          if (a.y < a.r || a.y > H - a.r) a.vy *= -1;
        }
        drawAsteroid(a);

        if (S.mode === "play") {
          const dx = a.x - 90;
          const dy = a.y - S.y;
          if (dx * dx + dy * dy < (a.r + 13) * (a.r + 13)) {
            if (hit(a.x, a.y)) return false;
            return false; // shield destroyed it
          }
          // near-miss bonus: squeeze past closely and get rewarded
          if (!a.passed && a.x < 70) {
            a.passed = true;
            if (Math.abs(dy) < a.r + 32) {
              S.score += 5;
              popup(90, S.y - 26, "close call! +5", "#ffd166");
            }
          }
        }
        return a.x > -50;
      });

      // ---- comets (with glowing trails) ----
      S.comets = S.comets.filter((c) => {
        if (S.mode === "play") {
          c.x += c.vx;
          c.y += c.vy;
        }
        // trail
        S.particles.push({
          x: c.x + 4,
          y: c.y,
          vx: 1 + Math.random(),
          vy: (Math.random() - 0.5) * 0.6,
          life: 18,
          max: 18,
          color: Math.random() < 0.5 ? "#ffd166" : "#ff9f43",
          r: 2 + Math.random() * 2,
        });
        ctx.save();
        ctx.shadowColor = "#ffd166";
        ctx.shadowBlur = 14;
        ctx.fillStyle = "#ffe8b0";
        ctx.beginPath();
        ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        if (S.mode === "play") {
          const dx = c.x - 90;
          const dy = c.y - S.y;
          if (dx * dx + dy * dy < (c.r + 13) * (c.r + 13)) {
            if (hit(c.x, c.y)) return false;
            return false;
          }
        }
        return c.x > -30;
      });

      // ---- wifi packets (magnet pulls them) ----
      S.wifis = S.wifis.filter((wf) => {
        if (S.mode === "play") {
          wf.x -= S.speed;
          if (S.magnet > 0) {
            const dx = 90 - wf.x;
            const dy = S.y - wf.y;
            const d = Math.sqrt(dx * dx + dy * dy);
            if (d < 170) {
              wf.x += (dx / d) * 3.2;
              wf.y += (dy / d) * 3.2;
            }
          }
        }
        wf.pulse += 0.12;
        const glow = 6 + Math.sin(wf.pulse) * 3;
        ctx.save();
        ctx.shadowColor = "#00d4a0";
        ctx.shadowBlur = glow * 2;
        ctx.strokeStyle = "#00d4a0";
        ctx.lineWidth = 2.5;
        ctx.lineCap = "round";
        for (let i = 1; i <= 3; i++) {
          ctx.beginPath();
          ctx.arc(wf.x, wf.y + 8, i * 6, Math.PI * 1.25, Math.PI * 1.75);
          ctx.stroke();
        }
        ctx.fillStyle = "#00d4a0";
        ctx.beginPath();
        ctx.arc(wf.x, wf.y + 8, 2.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        if (S.mode === "play") {
          const dx = wf.x - 90;
          const dy = wf.y - S.y;
          if (dx * dx + dy * dy < 30 * 30) {
            S.combo = Math.min(S.combo + 1, 8);
            S.comboTimer = 180;
            const gain = 10 * S.combo;
            S.score += gain;
            S.packets++;
            burst(wf.x, wf.y, "#00d4a0", 14, 3);
            popup(wf.x, wf.y - 12, S.combo > 1 ? `+${gain} x${S.combo}!` : `+${gain}`);
            return false;
          }
        }
        return wf.x > -30;
      });

      // ---- power-ups ----
      S.powerups = S.powerups.filter((p) => {
        if (S.mode === "play") p.x -= S.speed;
        p.pulse += 0.1;
        const bob = Math.sin(p.pulse) * 5;
        ctx.save();
        ctx.shadowColor = p.kind === "shield" ? "#7df9ff" : "#ff9ff3";
        ctx.shadowBlur = 16;
        ctx.font = "24px serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(p.kind === "shield" ? "🛡️" : "🧲", p.x, p.y + bob);
        ctx.restore();

        if (S.mode === "play") {
          const dx = p.x - 90;
          const dy = p.y + bob - S.y;
          if (dx * dx + dy * dy < 32 * 32) {
            if (p.kind === "shield") {
              S.shield = true;
              popup(90, S.y - 30, "SHIELD UP 🛡️", "#7df9ff");
              burst(p.x, p.y, "#7df9ff", 16, 3);
            } else {
              S.magnet = 420; // ~7s
              popup(90, S.y - 30, "PACKET MAGNET 🧲", "#ff9ff3");
              burst(p.x, p.y, "#ff9ff3", 16, 3);
            }
            return false;
          }
        }
        return p.x > -30;
      });

      // ---- particles ----
      S.particles = S.particles.filter((p) => {
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        ctx.globalAlpha = Math.max(0, p.life / p.max);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
        return p.life > 0;
      });
      ctx.globalAlpha = 1;

      // ---- astronaut ----
      if (S.mode !== "dead") {
        const tilt =
          S.mode === "play" ? Math.max(-0.35, Math.min(0.4, S.vy * 0.07)) : 0;
        const idleBob = S.mode === "idle" ? Math.sin(S.frame / 25) * 6 : 0;
        ctx.save();
        ctx.translate(90, S.y + idleBob);
        ctx.rotate(tilt);
        // soft aura so the hero reads against the busy background
        const aura = ctx.createRadialGradient(0, 0, 4, 0, 0, 26);
        aura.addColorStop(0, "rgba(0,212,160,.22)");
        aura.addColorStop(1, "rgba(0,212,160,0)");
        ctx.fillStyle = aura;
        ctx.beginPath();
        ctx.arc(0, 0, 26, 0, TAU);
        ctx.fill();
        // shield bubble
        if (S.shield) {
          ctx.strokeStyle = "rgba(125,249,255,.7)";
          ctx.lineWidth = 2;
          ctx.shadowColor = "#7df9ff";
          ctx.shadowBlur = 12;
          ctx.beginPath();
          ctx.arc(0, 0, 24 + Math.sin(S.frame / 8) * 2, 0, Math.PI * 2);
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
        if (S.thrust) {
          ctx.shadowColor = "#00d4a0";
          ctx.shadowBlur = 22;
        }
        ctx.font = "34px serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("👨‍🚀", 0, 0);
        ctx.restore();

        // magnet field ring
        if (S.magnet > 0 && S.mode === "play") {
          ctx.strokeStyle = `rgba(255,159,243,${0.15 + 0.1 * Math.sin(S.frame / 6)})`;
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.arc(90, S.y, 60, 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      // ---- cinematic vignette (adds depth, drawn over the world) ----
      const vig = ctx.createRadialGradient(
        W / 2,
        H / 2,
        H * 0.32,
        W / 2,
        H / 2,
        W * 0.62
      );
      vig.addColorStop(0, "rgba(3,5,10,0)");
      vig.addColorStop(1, "rgba(3,5,10,0.55)");
      ctx.fillStyle = vig;
      ctx.fillRect(0, 0, W, H);

      // ---- popups ----
      S.popups = S.popups.filter((p) => {
        p.y -= 0.8;
        p.life--;
        ctx.globalAlpha = Math.max(0, p.life / 50);
        ctx.fillStyle = p.color;
        ctx.font = "bold 15px -apple-system, 'Segoe UI', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(p.text, p.x, p.y);
        return p.life > 0;
      });
      ctx.globalAlpha = 1;

      // ---- HUD ----
      ctx.textAlign = "left";
      ctx.fillStyle = "#c9d1d9";
      ctx.font = "bold 16px -apple-system, 'Segoe UI', sans-serif";
      ctx.fillText(`${Math.floor(S.score)}`, 14, 26);
      ctx.fillStyle = "#8b949e";
      ctx.font = "11px -apple-system, 'Segoe UI', sans-serif";
      ctx.fillText(`LVL ${S.level} · ${lv.name.toUpperCase()} · 📶 ${S.packets}`, 14, 44);
      if (S.combo > 1 && S.mode === "play") {
        ctx.fillStyle = "#00d4a0";
        ctx.font = "bold 14px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText(`combo x${S.combo}`, 14, 64);
        ctx.fillStyle = "rgba(0,212,160,.25)";
        ctx.fillRect(14, 70, 60, 4);
        ctx.fillStyle = "#00d4a0";
        ctx.fillRect(14, 70, (S.comboTimer / 180) * 60, 4);
      }
      if (S.magnet > 0 && S.mode === "play") {
        ctx.fillStyle = "#ff9ff3";
        ctx.font = "11px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText(`🧲 ${Math.ceil(S.magnet / 60)}s`, 14, 88);
      }

      // ---- level-up banner ----
      if (S.levelBanner > 0 && S.mode === "play") {
        S.levelBanner--;
        const a = Math.min(1, S.levelBanner / 30);
        ctx.globalAlpha = a;
        ctx.fillStyle = "#ffd166";
        ctx.font = "bold 24px -apple-system, 'Segoe UI', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(
          S.level === 1 ? "🚀 LAUNCH!" : `LEVEL ${S.level}`,
          W / 2,
          H / 2 - 40
        );
        ctx.fillStyle = "#fff";
        ctx.font = "14px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText(lv.name, W / 2, H / 2 - 16);
        ctx.globalAlpha = 1;
      }

      // ---- idle / dead overlays ----
      ctx.textAlign = "center";
      if (S.mode === "idle") {
        ctx.fillStyle = "#fff";
        ctx.font = "bold 19px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText("🚀 JETPACK ESCAPE", W / 2, H / 2 - 34);
        ctx.fillStyle = "#c9d1d9";
        ctx.font = "14px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText(
          "HOLD to fly up · release to drift down · grab 📶 🛡️ 🧲 · dodge everything else",
          W / 2,
          H / 2 - 8
        );
        ctx.fillStyle = "#00d4a0";
        ctx.font = "bold 14px -apple-system, 'Segoe UI', sans-serif";
        if (Math.sin(S.frame / 15) > -0.3)
          ctx.fillText("press & hold space — or hold tap — to launch", W / 2, H / 2 + 22);
      } else if (S.mode === "dead") {
        ctx.fillStyle = "rgba(5,8,14,.55)";
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = "#ff6b6b";
        ctx.font = "bold 20px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText("💥 LOST IN SPACE", W / 2, H / 2 - 34);
        ctx.fillStyle = "#fff";
        ctx.font = "15px -apple-system, 'Segoe UI', sans-serif";
        ctx.fillText(
          `score ${Math.floor(S.score)} · level ${S.level} · packets ${S.packets}`,
          W / 2,
          H / 2 - 8
        );
        if (S.deadCooldown <= 0) {
          ctx.fillStyle = "#00d4a0";
          ctx.font = "bold 13px -apple-system, 'Segoe UI', sans-serif";
          ctx.fillText("press space or tap to fly again", W / 2, H / 2 + 20);
        }
      }

      ctx.restore();
    };
    loop();

    return () => {
      cancelAnimationFrame(S.raf);
      window.removeEventListener("keydown", press);
      window.removeEventListener("keyup", release);
      canvas.removeEventListener("pointerdown", press);
      window.removeEventListener("pointerup", release);
      window.removeEventListener("resize", onResize);
    };
  }, []);

  return (
    <div style={{ marginTop: 26, width: "100%", maxWidth: W }}>
      <canvas
        ref={canvasRef}
        width={W}
        height={BASE_H}
        style={{
          width: "100%",
          maxWidth: W,
          height: "auto",
          border: "1px solid rgba(0,212,160,.25)",
          borderRadius: 14,
          background: "#070c16",
          cursor: "pointer",
          touchAction: "none",
          boxShadow: "0 0 40px rgba(0,212,160,.08)",
        }}
      />
      <div style={{ fontSize: 12, color: "#8b949e", marginTop: 8 }}>
        hold space / hold tap to fly{best > 0 ? ` · best: ${best}` : ""}
      </div>
    </div>
  );
}
