/* ============================================
   🔗 SLUGIFY
   Shared between the React app and the build-time
   prerender script (scripts/prerender.js), so a
   project's URL is identical in both places.

   Written as CommonJS on purpose: webpack imports it
   fine from the app, and scripts/prerender.js can
   require() it directly under plain Node.

   Every project in portfolio.js carries an explicit
   `slug` — that is the stable, canonical URL. The
   derived fallback only exists so a newly added
   project without a slug still gets a working URL
   instead of crashing.
   ============================================ */

// Emoji, variation selectors and ZWJ — project names are full of them.
const EMOJI = /[←-⇿⌀-⏿─-➿⬀-⯿️‍]|[\uD800-\uDBFF][\uDC00-\uDFFF]/g;

// Strip emoji, accents and punctuation down to a-z0-9 + hyphens.
function slugify(input) {
  return String(input || "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "") // combining accents
    .replace(EMOJI, " ")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80)
    .replace(/-+$/, "");
}

// Project names carry a leading/inline emoji for the UI. Titles, meta
// descriptions and JSON-LD want the plain text.
function cleanName(name) {
  return String(name || "")
    .replace(EMOJI, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// The canonical slug for a project: explicit wins, derived is the fallback.
function projectSlug(project) {
  return project && project.slug
    ? project.slug
    : slugify(project && project.name);
}

function findProjectBySlug(list, slug) {
  if (!slug) return null;
  return (list || []).find((p) => projectSlug(p) === slug) || null;
}

module.exports = { slugify, cleanName, projectSlug, findProjectBySlug };
