/**
 * 🧠 VISITOR INTELLIGENCE SERVICE
 *
 * Tracks, analyzes, and predicts visitor behavior
 * Powers the predictive features of the portfolio
 */

import { db } from "../firebase/config";
import {
  doc,
  setDoc,
  getDoc,
  updateDoc,
  serverTimestamp,
  increment,
  arrayUnion,
} from "firebase/firestore";

// Generate or retrieve visitor ID
const getVisitorId = () => {
  let visitorId = localStorage.getItem("portfolio_visitor_id");
  if (!visitorId) {
    visitorId =
      "visitor_" + Date.now() + "_" + Math.random().toString(36).substr(2, 9);
    localStorage.setItem("portfolio_visitor_id", visitorId);
  }
  return visitorId;
};

// utm_source value -> visitor type. Shares from the site itself are tagged
// (see components/share/shareLinks.js), as are the résumé and GitHub README
// links, so "direct" stops swallowing them.
const UTM_TYPES = {
  linkedin: ["recruiter", 0.85],
  resume: ["recruiter", 0.8],
  github: ["developer", 0.9],
  hackernews: ["techie", 0.85],
  producthunt: ["techie", 0.85],
  devto: ["techie", 0.85],
  twitter: ["social", 0.75],
  x: ["social", 0.75],
  whatsapp: ["social", 0.7],
  reddit: ["social", 0.7],
  facebook: ["social", 0.7],
  instagram: ["social", 0.7],
  email: ["social", 0.65],
  copy_link: ["social", 0.6],
  native_share: ["social", 0.6],
};

/** utm_* from the landing URL (null when untagged). */
const readUtm = () => {
  const params = new URLSearchParams(window.location.search);
  const source = (params.get("utm_source") || "").toLowerCase().trim();
  if (!source) return null;
  return {
    source: source.slice(0, 40),
    medium: (params.get("utm_medium") || "").toLowerCase().slice(0, 40),
    campaign: (params.get("utm_campaign") || "").toLowerCase().slice(0, 60),
  };
};

// Detect visitor type: an explicit utm_source wins, then the referrer
const detectVisitorType = (utm) => {
  const referrer = document.referrer.toLowerCase();

  if (utm) {
    const [type, confidence] = UTM_TYPES[utm.source] || ["unknown", 0.5];
    return { type, confidence, source: utm.source };
  }

  if (referrer.includes("linkedin")) {
    return { type: "recruiter", confidence: 0.85, source: "linkedin" };
  }
  if (referrer.includes("github")) {
    return { type: "developer", confidence: 0.9, source: "github" };
  }
  if (referrer.includes("google") || referrer.includes("bing")) {
    return { type: "searcher", confidence: 0.7, source: "search" };
  }
  if (
    referrer.includes("twitter") ||
    referrer.includes("x.com") ||
    referrer.includes("t.co/")
  ) {
    return { type: "social", confidence: 0.75, source: "twitter" };
  }
  if (referrer.includes("producthunt") || referrer.includes("ycombinator")) {
    return { type: "techie", confidence: 0.85, source: "tech-community" };
  }
  if (!referrer) {
    return { type: "direct", confidence: 0.6, source: "direct" };
  }

  return { type: "unknown", confidence: 0.5, source: referrer };
};

// Calculate lead score based on behavior
const calculateLeadScore = (visitorData) => {
  let score = 0;

  // Visit frequency (max 25 points)
  score += Math.min(visitorData.totalVisits * 5, 25);

  // Time spent (max 25 points)
  const minutesSpent = (visitorData.totalTimeSpent || 0) / 60;
  score += Math.min(minutesSpent * 2, 25);

  // Sections viewed (max 20 points)
  const sectionsViewed = visitorData.sectionsViewed?.length || 0;
  score += Math.min(sectionsViewed * 4, 20);

  // Key actions (max 30 points)
  if (visitorData.viewedProjects) score += 10;
  if (visitorData.viewedContact) score += 10;
  if (visitorData.interactedWithAI) score += 10;

  // Visitor type bonus
  if (visitorData.detectedType === "recruiter") score += 15;
  if (visitorData.detectedType === "developer") score += 10;

  // Round: the time component is fractional, and an unrounded 35.633333…
  // is what the dashboard would otherwise have to render.
  return Math.round(Math.min(score, 100));
};

/* ---------------- page + location helpers ---------------- */

/** "/projects/rag-bot" -> "projects_rag-bot"; "/" -> "home". Firestore map
 *  keys can't hold "/" or "." safely inside a dotted field path. */
export const pageKey = (path) =>
  String(path || "/")
    .split("?")[0]
    .replace(/^\/+|\/+$/g, "")
    .replace(/[/.]+/g, "_")
    .replace(/[^\w-]/g, "")
    .slice(0, 80) || "home";

const GEO_CACHE_KEY = "portfolio_geo";
const GEO_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;

/**
 * City-level location from the visitor's IP. Two keyless HTTPS providers,
 * first answer wins; cached for a week so a visitor costs one lookup. The
 * raw IP is deliberately not kept — only what the dashboard shows.
 */
const lookupGeo = async () => {
  try {
    const cached = JSON.parse(localStorage.getItem(GEO_CACHE_KEY) || "null");
    if (cached && Date.now() - cached.at < GEO_MAX_AGE_MS) return cached.geo;
  } catch {
    /* corrupt cache — refetch */
  }

  const providers = [
    async () => {
      const r = await fetch(
        "https://ipwho.is/?fields=success,city,region,country,country_code,latitude,longitude,connection"
      );
      const d = await r.json();
      if (!d.success) throw new Error("ipwho.is failed");
      return {
        city: d.city || "",
        region: d.region || "",
        country: d.country || "",
        countryCode: d.country_code || "",
        lat: d.latitude,
        lon: d.longitude,
        org: d.connection?.org || d.connection?.isp || "",
        source: "ipwho.is",
      };
    },
    async () => {
      const r = await fetch("https://ipapi.co/json/");
      const d = await r.json();
      if (d.error) throw new Error(d.reason || "ipapi.co failed");
      return {
        city: d.city || "",
        region: d.region || "",
        country: d.country_name || "",
        countryCode: d.country_code || "",
        lat: d.latitude,
        lon: d.longitude,
        org: d.org || "",
        source: "ipapi.co",
      };
    },
  ];

  for (const provider of providers) {
    try {
      const geo = await provider();
      if (typeof geo.lat === "number" && typeof geo.lon === "number") {
        localStorage.setItem(
          GEO_CACHE_KEY,
          JSON.stringify({ at: Date.now(), geo })
        );
        return geo;
      }
    } catch (err) {
      console.warn("Geo lookup:", err.message);
    }
  }
  return null;
};

const HEARTBEAT_MS = 60 * 1000;

// Main Intelligence Class
class VisitorIntelligenceService {
  constructor() {
    this.visitorId = getVisitorId();
    this.sessionStart = Date.now();
    // saveSessionData() can fire several times per session (every tab-hide).
    // Track what we've already banked so time isn't counted twice.
    this.lastSaveAt = this.sessionStart;
    this.savedPatternCount = 0;
    this.currentSection = "home";
    this.hoverData = {};
    this.clickData = [];
    this.scrollDepth = 0;
    this.isReturning = false;
    this.visitorProfile = null;
    this.behaviorPatterns = [];
    this.predictions = [];
    // Writes that race initialize() (a Jarvis question, a route change) wait
    // for the visitor doc to exist instead of failing on updateDoc.
    this.ready = new Promise((resolve) => {
      this.markReady = resolve;
    });
    this.currentPage = null;
    this.pageEnteredAt = Date.now();
    // Read the landing URL now: initialize() runs on idle, by which time an
    // in-app navigation may already have dropped the ?utm_ params.
    this.entryUtm = readUtm();
    this.entryPath = window.location.pathname;
    this.entry = detectVisitorType(this.entryUtm);
    this.heartbeat = null;
  }

  // Initialize and load visitor data
  async initialize() {
    try {
      const visitorRef = doc(db, "visitors", this.visitorId);
      const visitorSnap = await getDoc(visitorRef);

      const detectedInfo = this.entry;
      const session = {
        start: new Date().toISOString(),
        referrer: document.referrer,
        userAgent: navigator.userAgent,
        landing: this.entryPath,
        source: detectedInfo.source,
        ...(this.entryUtm ? { utm: this.entryUtm } : {}),
      };

      if (visitorSnap.exists()) {
        // Returning visitor
        this.isReturning = true;
        this.visitorProfile = visitorSnap.data();

        // Update visit count
        await updateDoc(visitorRef, {
          totalVisits: increment(1),
          lastSeen: serverTimestamp(),
          sessions: arrayUnion(session),
          lastSource: detectedInfo.source,
          ...(this.entryUtm ? { lastUtm: this.entryUtm } : {}),
        });

        console.log("🔄 Returning visitor detected:", this.visitorId);
        this.afterInit();
        return {
          isReturning: true,
          profile: this.visitorProfile,
          lastVisit: this.visitorProfile.lastSeen?.toDate?.() || null,
          interests: this.visitorProfile.interests || [],
          previousQuestions: this.visitorProfile.aiQuestions || [],
        };
      } else {
        // New visitor
        this.isReturning = false;

        const newProfile = {
          visitorId: this.visitorId,
          firstSeen: serverTimestamp(),
          lastSeen: serverTimestamp(),
          totalVisits: 1,
          totalTimeSpent: 0,
          detectedType: detectedInfo.type,
          typeConfidence: detectedInfo.confidence,
          referralSource: detectedInfo.source,
          fullReferrer: document.referrer,
          userAgent: navigator.userAgent,
          screenSize: `${window.screen.width}x${window.screen.height}`,
          timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
          language: navigator.language,
          sectionsViewed: [],
          projectsViewed: [],
          aiQuestions: [],
          interests: [],
          leadScore: 0,
          sessions: [session],
          ...(this.entryUtm
            ? { utm: this.entryUtm, lastUtm: this.entryUtm }
            : {}),
          lastSource: detectedInfo.source,
          landingPage: this.entryPath,
          pagesViewed: [],
          pageViews: {},
          pageTime: {},
        };

        await setDoc(visitorRef, newProfile);
        this.visitorProfile = newProfile;

        console.log(
          "🆕 New visitor tracked:",
          this.visitorId,
          "Type:",
          detectedInfo.type
        );
        this.afterInit();
        return {
          isReturning: false,
          profile: newProfile,
          detectedType: detectedInfo,
        };
      }
    } catch (error) {
      console.error("❌ Visitor intelligence error:", error);
      this.markReady(); // queued writes fail fast instead of waiting forever
      return { isReturning: false, profile: null, error };
    }
  }

  /** Doc exists: release queued writes, record the page, locate, heartbeat. */
  afterInit() {
    this.markReady();
    this.trackPageView(window.location.pathname);
    this.saveGeo();
    if (!this.heartbeat) {
      this.heartbeat = setInterval(() => {
        if (document.visibilityState === "visible") this.saveSessionData();
      }, HEARTBEAT_MS);
    }
  }

  async saveGeo() {
    // Refresh at most weekly; lookupGeo() serves the cache in between.
    const known = this.visitorProfile?.geo;
    const at = known?.updatedAt ? Date.parse(known.updatedAt) : 0;
    if (known && Date.now() - at < GEO_MAX_AGE_MS) return;
    const geo = await lookupGeo();
    if (!geo) return;
    try {
      const payload = { ...geo, updatedAt: new Date().toISOString() };
      await updateDoc(doc(db, "visitors", this.visitorId), { geo: payload });
      this.visitorProfile = { ...this.visitorProfile, geo: payload };
    } catch (error) {
      console.warn("Geo save error:", error);
    }
  }

  /**
   * One write per route change: counts the view, banks the seconds spent on
   * the page being left, and records where the visitor is right now.
   */
  async trackPageView(path) {
    const next = String(path || "/").split("?")[0];
    if (next === this.currentPage) return;
    // The owner's admin dashboard isn't a portfolio page
    if (next.startsWith("/admin")) return;
    const prev = this.currentPage;
    const now = Date.now();
    const seconds = Math.round((now - this.pageEnteredAt) / 1000);
    this.currentPage = next;
    this.pageEnteredAt = now;

    await this.ready;
    const key = pageKey(next);
    const payload = {
      currentPage: next,
      pagesViewed: arrayUnion(next),
      [`pageViews.${key}`]: increment(1),
      lastSeen: serverTimestamp(),
    };
    if (prev && seconds > 0 && seconds < 6 * 3600) {
      payload[`pageTime.${pageKey(prev)}`] = increment(seconds);
    }
    if (next.startsWith("/projects")) payload.viewedProjects = true;
    if (next.startsWith("/contact")) payload.viewedContact = true;
    try {
      await updateDoc(doc(db, "visitors", this.visitorId), payload);
    } catch (error) {
      console.warn("Page view tracking error:", error);
    }
  }

  /** Contact form sent: link the lead to this visitor record. */
  async trackContact(email, subject = "") {
    await this.ready;
    try {
      await updateDoc(doc(db, "visitors", this.visitorId), {
        email: String(email || "").slice(0, 120),
        contacted: true,
      });
    } catch (error) {
      console.warn("Contact tracking error:", error);
    }
    this.trackEvent("contact_submit", subject);
  }

  /** Discrete actions: resume download, outbound click, contact submit… */
  async trackEvent(type, label = "") {
    await this.ready;
    const safeType = String(type)
      .replace(/[^\w-]/g, "_")
      .slice(0, 40);
    try {
      await updateDoc(doc(db, "visitors", this.visitorId), {
        [`eventCounts.${safeType}`]: increment(1),
        events: arrayUnion({
          type: safeType,
          label: String(label).slice(0, 120),
          page: window.location.pathname,
          timestamp: new Date().toISOString(),
        }),
        lastSeen: serverTimestamp(),
      });
    } catch (error) {
      console.warn("Event tracking error:", error);
    }
  }

  // Track section view
  async trackSectionView(sectionName) {
    this.currentSection = sectionName;

    try {
      const visitorRef = doc(db, "visitors", this.visitorId);
      await updateDoc(visitorRef, {
        sectionsViewed: arrayUnion(sectionName),
        lastSection: sectionName,
        [`sectionTime.${sectionName}`]: increment(1),
      });

      // Update predictions based on section
      this.updatePredictions(sectionName);
    } catch (error) {
      console.warn("Section tracking error:", error);
    }
  }

  // Track hover behavior
  trackHover(elementId, duration) {
    if (!this.hoverData[elementId]) {
      this.hoverData[elementId] = { count: 0, totalDuration: 0 };
    }
    this.hoverData[elementId].count++;
    this.hoverData[elementId].totalDuration += duration;

    // If hovering for more than 3 seconds, it's significant interest
    if (duration > 3000) {
      this.behaviorPatterns.push({
        type: "extended_hover",
        element: elementId,
        duration,
        timestamp: Date.now(),
      });
    }
  }

  // Track scroll depth
  trackScroll(depth) {
    if (depth > this.scrollDepth) {
      this.scrollDepth = depth;

      // Track significant scroll milestones
      if (
        depth >= 75 &&
        !this.behaviorPatterns.find((p) => p.type === "deep_scroll")
      ) {
        this.behaviorPatterns.push({
          type: "deep_scroll",
          depth,
          timestamp: Date.now(),
        });
      }
    }
  }

  // Track AI interaction
  async trackAIInteraction(question, meta = {}) {
    const text = String(question || "").trim();
    if (!text) return;
    await this.ready;
    try {
      const visitorRef = doc(db, "visitors", this.visitorId);
      await updateDoc(visitorRef, {
        interactedWithAI: true,
        aiQuestionCount: increment(1),
        aiQuestions: arrayUnion({
          question: text.slice(0, 300),
          source: meta.source || "chat",
          page: window.location.pathname,
          timestamp: new Date().toISOString(),
        }),
        lastAIInteraction: serverTimestamp(),
        lastSeen: serverTimestamp(),
      });

      // Analyze question for interests
      const interests = this.extractInterests(text);
      if (interests.length > 0) {
        await updateDoc(visitorRef, {
          interests: arrayUnion(...interests),
        });
      }
    } catch (error) {
      console.warn("AI interaction tracking error:", error);
    }
  }

  // Extract interests from question
  extractInterests(question) {
    const interests = [];
    const q = question.toLowerCase();

    if (
      q.includes("python") ||
      q.includes("java") ||
      q.includes("javascript")
    ) {
      interests.push("programming");
    }
    if (
      q.includes("ai") ||
      q.includes("ml") ||
      q.includes("machine learning")
    ) {
      interests.push("ai_ml");
    }
    if (q.includes("project") || q.includes("work") || q.includes("built")) {
      interests.push("projects");
    }
    if (q.includes("hire") || q.includes("available") || q.includes("rate")) {
      interests.push("hiring");
    }
    if (q.includes("contact") || q.includes("email") || q.includes("reach")) {
      interests.push("contact");
    }
    if (q.includes("experience") || q.includes("background")) {
      interests.push("experience");
    }

    return interests;
  }

  // Update predictions based on behavior
  updatePredictions(currentSection) {
    this.predictions = [];

    // Based on section patterns
    if (
      currentSection === "projects" &&
      this.visitorProfile?.detectedType === "recruiter"
    ) {
      this.predictions.push({
        action: "show_contact_cta",
        confidence: 0.8,
        message: "Interested in Laxman's work? Let's schedule a call!",
      });
    }

    if (currentSection === "experience" && this.scrollDepth > 50) {
      this.predictions.push({
        action: "offer_resume",
        confidence: 0.75,
        message: "Want a detailed resume? I can send it to your email!",
      });
    }

    if (this.hoverData["ai-projects"]?.totalDuration > 5000) {
      this.predictions.push({
        action: "ai_demo",
        confidence: 0.85,
        message:
          "I see you're interested in AI! Want me to walk you through Laxman's RAG system?",
      });
    }

    return this.predictions;
  }

  // Get prediction for proactive popup
  getPrediction() {
    if (this.predictions.length === 0) return null;

    // Return highest confidence prediction
    return this.predictions.sort((a, b) => b.confidence - a.confidence)[0];
  }

  // Check if should show exit intent popup
  shouldShowExitIntent() {
    // Don't show if already shown in this session
    if (sessionStorage.getItem("exit_intent_shown")) return false;

    // Don't show for very short visits
    const timeOnSite = (Date.now() - this.sessionStart) / 1000;
    if (timeOnSite < 10) return false;

    // Show for engaged visitors
    return this.scrollDepth > 25 || this.behaviorPatterns.length > 0;
  }

  // Get personalized greeting for returning visitor
  getPersonalizedGreeting() {
    if (!this.isReturning || !this.visitorProfile) {
      return null;
    }

    const lastVisit = this.visitorProfile.lastSeen?.toDate?.();
    const interests = this.visitorProfile.interests || [];
    const previousQuestions = this.visitorProfile.aiQuestions || [];

    let greeting = "Welcome back! ";

    if (lastVisit) {
      const daysSince = Math.floor(
        (Date.now() - lastVisit.getTime()) / (1000 * 60 * 60 * 24)
      );
      if (daysSince === 0) {
        greeting += "Good to see you again today! ";
      } else if (daysSince === 1) {
        greeting += "Nice to see you again! ";
      } else {
        greeting += `It's been ${daysSince} days since your last visit! `;
      }
    }

    if (interests.includes("projects")) {
      greeting += "I have some new project updates for you!";
    } else if (interests.includes("hiring")) {
      greeting += "Ready to discuss opportunities?";
    } else if (previousQuestions.length > 0) {
      greeting += "Shall we continue where we left off?";
    } else {
      greeting += "How can I help you today?";
    }

    return greeting;
  }

  // Save session data before leaving
  async saveSessionData() {
    // Only the time since the last save, so repeated tab-hides don't
    // multiply totalTimeSpent.
    const elapsed = Math.floor((Date.now() - this.lastSaveAt) / 1000);
    if (elapsed < 2) return;

    // Nothing to write against yet — initialize() hasn't created the doc.
    if (!this.visitorProfile) return;

    const totalSoFar = Math.floor((Date.now() - this.sessionStart) / 1000);

    try {
      const visitorRef = doc(db, "visitors", this.visitorId);
      const newLeadScore = calculateLeadScore({
        ...this.visitorProfile,
        totalTimeSpent: (this.visitorProfile?.totalTimeSpent || 0) + totalSoFar,
      });

      const payload = {
        totalTimeSpent: increment(elapsed),
        currentPage: this.currentPage || window.location.pathname,
        lastScrollDepth: this.scrollDepth,
        hoverPatterns: this.hoverData,
        leadScore: newLeadScore,
        lastSeen: serverTimestamp(),
      };

      // Bank time on the page being viewed, so a visitor who never navigates
      // still shows up in per-page time.
      if (this.currentPage) {
        const onPage = Math.round((Date.now() - this.pageEnteredAt) / 1000);
        if (onPage > 0 && onPage < 6 * 3600) {
          payload[`pageTime.${pageKey(this.currentPage)}`] = increment(onPage);
          this.pageEnteredAt = Date.now();
        }
      }

      // arrayUnion() throws when called with zero arguments, which used to
      // fail the whole write — and with it every time/score update.
      const newPatterns = this.behaviorPatterns.slice(this.savedPatternCount);
      if (newPatterns.length > 0) {
        payload.behaviorPatterns = arrayUnion(...newPatterns);
      }

      await updateDoc(visitorRef, payload);

      this.lastSaveAt = Date.now();
      this.savedPatternCount = this.behaviorPatterns.length;

      console.log("💾 Session data saved. +", elapsed, "seconds");
    } catch (error) {
      console.warn("Session save error:", error);
    }
  }
}

// Singleton instance
let intelligenceInstance = null;

export const getVisitorIntelligence = () => {
  if (!intelligenceInstance) {
    intelligenceInstance = new VisitorIntelligenceService();
  }
  return intelligenceInstance;
};

export default VisitorIntelligenceService;
