/* Shared bookends. The prelude is offered inside every path rather than
   sitting at the top of the page, because "here are seven things about
   tokenisation" is a terrible first screen for someone who came to find out
   how to build an agent. */
const PRELUDE_TRACK = "basics";
const OUTRO_TRACK = "interview";

/* ---------------------------------------------------------------------
   Derived values. Pure functions, no imports — the prerenderer calls
   these too, so they must run under plain Node.
   --------------------------------------------------------------------- */

function trackOf(id) {
  return tracks.find((t) => t.id === id) || null;
}

/** A path with its track objects resolved, prelude and outro included. */
function resolvePath(path) {
  if (!path) return null;
  return {
    ...path,
    prelude: trackOf(PRELUDE_TRACK),
    outro: trackOf(OUTRO_TRACK),
    tracks: path.trackIds.map(trackOf).filter(Boolean),
  };
}

function allPaths() {
  return paths.map(resolvePath);
}

function pathById(id) {
  return resolvePath(paths.find((p) => p.id === id));
}

/** Every path a track appears in — evals appears in all three. */
function pathsOfTrack(trackId) {
  return paths.filter((p) => p.trackIds.includes(trackId));
}

/** Core hours, excluding the optional prelude and the interview rail. */
function pathHours(path) {
  return (path.tracks || []).reduce((sum, t) => sum + (t.hours || 0), 0);
}

function pathStageCount(path) {
  return (path.tracks || []).reduce((sum, t) => sum + t.stages.length, 0);
}

function allStages() {
  const out = [];
  tracks.forEach((t) =>
    t.stages.forEach((s) => out.push({ track: t, stage: s }))
  );
  return out;
}

function allResources() {
  const out = [];
  tracks.forEach((t) =>
    t.stages.forEach((s) => (s.resources || []).forEach((r) => out.push(r)))
  );
  return out;
}

function totalHours() {
  return tracks.reduce((sum, t) => sum + (t.hours || 0), 0);
}

function stageCount() {
  return tracks.reduce((sum, t) => sum + t.stages.length, 0);
}

function freeCount() {
  return allResources().filter((r) => r.cost === "free").length;
}

/* What a track is actually made of. The resources are the substance of this
   page and they all sit behind a closed row, so the row itself has to be able
   to say "six videos, two papers, all free" without being opened. */
function trackMix(track) {
  const by = {};
  let free = 0;
  let count = 0;
  (track.stages || []).forEach((st) =>
    (st.resources || []).forEach((r) => {
      by[r.type] = (by[r.type] || 0) + 1;
      count += 1;
      if (r.cost === "free") free += 1;
    })
  );
  return { by, free, count };
}

function trackById(id) {
  return tracks.find((t) => t.id === id) || null;
}

/** Oldest `checkedOn` across every resource — the honest "last reviewed". */
function lastReviewed() {
  const dates = allResources()
    .map((r) => r.checkedOn)
    .filter(Boolean)
    .sort();
  return dates[0] || null;
}

/** "2026-08" → "August 2026" */
function monthName(ym) {
  if (!ym) return "";
  const MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const [y, m] = String(ym).split("-").map(Number);
  return `${MONTHS[m - 1]} ${y}`;
}

