import React, { useEffect, useRef, useState } from "react";
import OfflineGame from "./OfflineGame";

/* ============================================
   📡 OFFLINE OVERLAY
   Full-screen page shown when the user's internet
   drops while browsing: starry sky, animated WiFi
   search, rotating funny messages, and a "Back
   online" celebration on reconnect. Zero deps.
   ============================================ */

const MESSAGES = [
  "Your WiFi went out for milk and hasn't come back. 🥛",
  "The hamsters powering your internet fell asleep. 🐹💤",
  "Houston, we've lost the connection. 🛰️",
  "Even my AI assistant can't reach you without internet. 🤖📵",
  "Somewhere, a router is having an existential crisis. 📡",
  "Plot twist: it's not you, it's your ISP. 💔",
];

// Deterministic star field so it doesn't re-randomize on each render
const STARS = Array.from({ length: 40 }, (_, i) => ({
  left: (i * 37) % 100,
  top: (i * 53) % 100,
  size: 1 + ((i * 7) % 3),
  delay: (i % 10) * 0.4,
}));

export default function OfflineOverlay() {
  const [offline, setOffline] = useState(!navigator.onLine);
  const [celebrating, setCelebrating] = useState(false);
  const [msgIndex, setMsgIndex] = useState(0);
  const wasOffline = useRef(!navigator.onLine);

  useEffect(() => {
    const goOffline = () => {
      wasOffline.current = true;
      setCelebrating(false);
      setOffline(true);
    };
    const goOnline = () => {
      // Show a brief "Back online" celebration before hiding
      if (wasOffline.current) {
        setCelebrating(true);
        setTimeout(() => {
          setOffline(false);
          setCelebrating(false);
          wasOffline.current = false;
        }, 1800);
      }
    };
    window.addEventListener("offline", goOffline);
    window.addEventListener("online", goOnline);
    return () => {
      window.removeEventListener("offline", goOffline);
      window.removeEventListener("online", goOnline);
    };
  }, []);

  // Rotate the funny message every 4s while offline
  useEffect(() => {
    if (!offline || celebrating) return;
    const id = setInterval(
      () => setMsgIndex((i) => (i + 1) % MESSAGES.length),
      4000
    );
    return () => clearInterval(id);
  }, [offline, celebrating]);

  if (!offline) return null;

  return (
    <div
      className="ol-overlay"
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 99999,
        background:
          "radial-gradient(ellipse at 22% 16%, rgba(0,212,160,.10) 0%, transparent 45%)," +
          "radial-gradient(ellipse at 82% 28%, rgba(125,90,220,.12) 0%, transparent 50%)," +
          "radial-gradient(ellipse at 50% 120%, #10233a 0%, #0a0f1a 55%, #05070d 100%)",
        color: "#c9d1d9",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        textAlign: "center",
        padding: "24px",
        // Scroll as a safety net so the game is never clipped on short/portrait
        // phones; media queries below top-align + shrink on small screens.
        overflowX: "hidden",
        overflowY: "auto",
        WebkitOverflowScrolling: "touch",
        fontFamily:
          "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
        animation: "olFadeIn .4s ease",
      }}
    >
      {/* Star field */}
      {STARS.map((s, i) => (
        <span
          key={i}
          style={{
            position: "absolute",
            left: `${s.left}%`,
            top: `${s.top}%`,
            width: s.size,
            height: s.size,
            borderRadius: "50%",
            background: "#fff",
            opacity: 0.5,
            animation: `olTwinkle 3s ease-in-out ${s.delay}s infinite`,
          }}
        />
      ))}

      {/* cinematic vignette — darkens the edges for depth */}
      <span
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          background:
            "radial-gradient(ellipse at 50% 45%, transparent 55%, rgba(3,5,10,.5) 100%)",
        }}
      />

      {celebrating ? (
        <>
          <div style={{ fontSize: 84, animation: "olPop .5s ease" }}>🎉</div>
          <h1 style={{ color: "#00d4a0", fontSize: 30, margin: "16px 0 8px" }}>
            Back online!
          </h1>
          <p style={{ color: "#8b949e", margin: 0 }}>
            Beaming you back to the portfolio…
          </p>
        </>
      ) : (
        <>
          {/* Astronaut floating with a dead WiFi signal */}
          <div style={{ position: "relative", height: 130 }}>
            <div
              className="ol-astro"
              style={{ fontSize: 90, animation: "olFloat 3.5s ease-in-out infinite" }}
            >
              👨‍🚀
            </div>
            {/* WiFi arcs searching */}
            <svg
              width="70"
              height="54"
              viewBox="0 0 70 54"
              style={{
                position: "absolute",
                top: -28,
                right: -44,
                animation: "olFloat 3.5s ease-in-out infinite",
              }}
            >
              <g fill="none" stroke="#00d4a0" strokeWidth="5" strokeLinecap="round">
                <path d="M25 44 a14 14 0 0 1 20 0" style={{ animation: "olWifi 1.8s infinite", animationDelay: "0s" }} />
                <path d="M16 34 a27 27 0 0 1 38 0" style={{ animation: "olWifi 1.8s infinite", animationDelay: ".25s" }} />
                <path d="M7 24 a40 40 0 0 1 56 0" style={{ animation: "olWifi 1.8s infinite", animationDelay: ".5s" }} />
              </g>
              <circle cx="35" cy="50" r="3.5" fill="#00d4a0" />
            </svg>
          </div>

          <h1 style={{ color: "#fff", fontSize: 30, margin: "20px 0 10px", letterSpacing: ".5px" }}>
            You're offline!
          </h1>

          {/* Rotating message — key forces the fade animation to replay */}
          <p
            key={msgIndex}
            style={{
              maxWidth: 440,
              fontSize: 18,
              lineHeight: 1.5,
              margin: "0 0 6px",
              minHeight: 54,
              animation: "olFadeIn .6s ease",
            }}
          >
            {MESSAGES[msgIndex]}
          </p>
          <p style={{ fontSize: 14, color: "#8b949e", margin: "0 0 20px" }}>
            No panic — the moment you reconnect, the portfolio comes right back.
          </p>

          <div
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 10,
              fontSize: 14,
              color: "#00d4a0",
              border: "1px solid rgba(0,212,160,.35)",
              borderRadius: 999,
              padding: "10px 22px",
              background: "rgba(0,212,160,.06)",
            }}
          >
            <span
              style={{
                width: 10,
                height: 10,
                borderRadius: "50%",
                background: "#00d4a0",
                animation: "olPulse 1.2s ease-in-out infinite",
              }}
            />
            searching for internet…
          </div>

          <OfflineGame />
        </>
      )}

      <style>
        {`@keyframes olPulse { 0%,100% { opacity:.2; transform:scale(.8) } 50% { opacity:1; transform:scale(1) } }
          @keyframes olFloat { 0%,100% { transform:translateY(0) rotate(-4deg) } 50% { transform:translateY(-14px) rotate(4deg) } }
          @keyframes olTwinkle { 0%,100% { opacity:.15 } 50% { opacity:.8 } }
          @keyframes olWifi { 0%,100% { opacity:.15 } 50% { opacity:1 } }
          @keyframes olFadeIn { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:translateY(0) } }
          @keyframes olPop { 0% { transform:scale(0) } 70% { transform:scale(1.25) } 100% { transform:scale(1) } }
          /* Short / portrait phones: top-align so the whole thing scrolls and
             the game is never clipped, and shrink the hero + headings to fit. */
          @media (max-height: 760px) { .ol-overlay { justify-content: flex-start !important; } }
          @media (max-width: 560px) {
            .ol-overlay h1 { font-size: 24px !important; }
            .ol-astro { font-size: 64px !important; }
          }`}
      </style>
    </div>
  );
}
