import React, { lazy, Suspense, useEffect, useState } from "react";
import { Route, Switch, useLocation } from "react-router-dom"; // Removed BrowserRouter
// SEO: per-route <title>, meta description & canonical (not lazy — tiny, must run early)
import RouteSeo from "../components/seo/RouteSeo";
import OfflineOverlay from "../components/offline/OfflineOverlay";
import { getVisitorIntelligence } from "../services/visitorIntelligence";
// Removed Splash import (It's in App.js now)

// Lazy imports
const Home = lazy(() => import("../pages/home/HomeComponent"));
const Education = lazy(() => import("../pages/education/EducationComponent"));
const Experience = lazy(() => import("../pages/experience/Experience"));
const Contact = lazy(() => import("../pages/contact/ContactComponent"));
const Projects = lazy(() => import("../pages/projects/Projects"));
const GithubPage = lazy(() => import("../pages/github/GithubPage"));
const Learn = lazy(() => import("../pages/learn/LearnComponent"));
const PortfolioChatBot = lazy(() => import("../components/chatbot/ChatBot"));

// Admin & User Pages
const AdminDashboard = lazy(() => import("../pages/admin/AdminDashboard"));
const UserSpace = lazy(() => import("../pages/userspace/UserSpace"));
const JarvisLive = lazy(() => import("../pages/userspace/jarvis/JarvisLive"));
const AIBlog = lazy(() => import("../pages/blog/AIBlog"));
const DreamLab = lazy(() => import("../pages/dreamlab/DreamLab"));
const JobHuntDashboard = lazy(() =>
  import("../pages/jobhunt/JobHuntDashboard")
);

export default function Main(propss) {
  const [isChatOpen, setIsChatOpen] = useState(false);
  const location = useLocation();

  // Visitor analytics: one page view per route change…
  // The admin dashboard is the owner's tool, not a portfolio page — keep it
  // out of the page stats.
  useEffect(() => {
    if (location.pathname.startsWith("/admin")) return;
    getVisitorIntelligence().trackPageView(location.pathname);
  }, [location.pathname]);

  // …and every outbound link / resume / mailto click, from one listener.
  useEffect(() => {
    const onClick = (e) => {
      const a = e.target.closest?.("a[href]");
      // Share buttons record their own "share" event
      if (!a || a.hasAttribute("data-no-outbound")) return;
      const href = a.getAttribute("href") || "";
      const intel = getVisitorIntelligence();
      // The résumé lives on Google Drive (viewer or direct-download URL)
      if (
        /\.pdf($|\?)|drive\.google\.com\/file|drive\.usercontent/i.test(href)
      ) {
        intel.trackEvent(
          "resume",
          a.dataset.track || a.textContent?.trim() || "resume"
        );
        return;
      }
      if (href.startsWith("mailto:"))
        intel.trackEvent("email_click", href.slice(7));
      else if (/^https?:\/\//i.test(href)) {
        try {
          const host = new URL(href).hostname.replace(/^www\./, "");
          if (host !== window.location.hostname)
            intel.trackEvent("outbound", host);
        } catch {
          /* malformed href — ignore */
        }
      }
    };
    document.addEventListener("click", onClick, true);
    return () => document.removeEventListener("click", onClick, true);
  }, []);
  // /myspace IS the AI workspace and /jarvis IS an assistant — the floating
  // chatbot (pill + promo popups + chat orb) is redundant on both and overlaps
  // their own UI. On /jarvis it is actively confusing: a second widget also
  // branded "JARVIS AI" sitting next to the real one.
  // The floating assistant now runs everywhere, /myspace and /jarvis included.
  //
  // It used to be hidden on both as redundant. On /myspace that was only ever
  // a judgement call about clutter. On /jarvis there was a concrete problem:
  // the widget calls itself "JARVIS AI", and the page it floats over *is*
  // Jarvis — two differently-branded bots under one name. So it is renamed
  // there rather than hidden, for what it actually answers: questions about
  // Laxman, not about Jarvis's source code.
  const chatBotLabels = location.pathname.startsWith("/jarvis")
    ? { button: "JARVIS", status: "Chat with me?" }
    : undefined;

  // Loading fallback
  const loadingFallback = (
    <div
      style={{
        height: "100vh",
        width: "100vw",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: propss.theme?.body || "#0a0a0a",
        color: propss.theme?.text || "#ffffff",
        fontSize: "18px",
      }}
    ></div>
  );

  return (
    <div className="main-content-container">
      <RouteSeo />
      <OfflineOverlay />
      {/*
         NOTE: BrowserRouter is removed from here. 
         It is now in App.js wrapping everything.
      */}
      <Suspense fallback={loadingFallback}>
        <Switch>
          {/* Jarvis — the live agent demo. Deliberately top-level and NOT
              nested under /myspace: it is a standalone open-source project,
              not part of the logged-in AI workspace. */}
          <Route
            path="/jarvis"
            render={(props) => (
              <JarvisLive
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />

          {/* User Space */}
          <Route
            path="/myspace"
            render={(props) => (
              <UserSpace
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />

          {/* Sandbox for the flying-dream character (not in the nav) */}
          <Route
            path="/dreamlab"
            render={() => <DreamLab theme={propss.theme} />}
          />

          {/* Job-Hunting Copilot */}
          <Route path="/jobhunt" render={() => <JobHuntDashboard />} />

          {/* AI Blog */}
          <Route
            path="/blog"
            render={(props) => (
              <AIBlog
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />

          {/* Admin */}
          <Route
            path="/admin"
            render={(props) => (
              <AdminDashboard
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />

          {/* 
             HOME ROUTES:
             Crucial: We render Home on both "/" and "/home".
             This ensures content is visible behind the splash screen.
          */}
          <Route
            path="/"
            exact
            render={(props) => (
              <Home
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          <Route
            path="/home"
            render={(props) => (
              <Home
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />

          {/* Other Pages */}
          <Route
            path="/experience"
            exact
            render={(props) => (
              <Experience
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          <Route
            path="/education"
            render={(props) => (
              <Education
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          <Route
            path="/contact"
            render={(props) => (
              <Contact
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          {/* /projects and /projects/:slug are the same page — the slug
              just opens that project's case study. Each slug is also a real
              prerendered file (scripts/prerender.js) so crawlers see it. */}
          <Route
            path="/projects/:slug?"
            render={(props) => (
              <Projects
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          {/* /learn and /learn/:track are the same page — the track segment
              only highlights the rail and scrolls. Each track is also a real
              prerendered file (scripts/prerender.js) so crawlers see it. */}
          <Route
            path="/learn/:track?"
            render={(props) => (
              <Learn
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
          <Route
            path="/github"
            render={(props) => (
              <GithubPage
                {...props}
                theme={propss.theme}
                setTheme={propss.setTheme}
              />
            )}
          />
        </Switch>

        {/* Wrapped in a slot so the Build IDE can hide the whole floating
            assistant (orb + promo bubbles) via `body.jvb-ide-open` without
            reaching into the chatbot's internals. */}
        <div className="site-chatbot-slot">
          <PortfolioChatBot theme={propss.theme} labels={chatBotLabels} />
        </div>
      </Suspense>
    </div>
  );
}
